SELECT id, sale_date, units, revenue, COUNT(revenue) OVER (PARTITION BY store_id ORDER BY sale_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_revenue, SUM(revenue) OVER (PARTITION BY store_id ORDER BY sale_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_revenue, AVG(revenue) OVER (PARTITION BY store_id ORDER BY sale_date ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_avg_revenue FROM store_sales
